scwin.autoComplete1_onviewchange = function(info) {
    focusFlag = true;
};
scwin.autoComplete2_onviewchange = function(info) {
    //			console.log("========== onviewchange ============");
    //alert("========== onviewchange ============");
    log = true;
};
scwin.autoComplete2_onchange = function() {
    //			console.log("========== onchange ============");
    //alert("========== onchange ============");
    log1 = true;
};
scwin.autoComplete2_onafteredit = function() {
    //			console.log("========== onafteredit ============");
    //alert("========== onafteredit ============");
    log2 = true;
};
scwin.checkVal1 = function() {
    return log;
}
scwin.checkVal2 = function() {
    return log1;
}
scwin.checkVal3 = function() {
    return log2;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 4. 브라우저에서 autoComplete 에 '경기' 를 입력한다. 
    //4. In the browser, enter 'Competition' in autoComplete.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2').focus()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_input').value = '경기'");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_input').value = ''");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_button').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2').focus()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. 입력된 데이터가 초기화 되면서 onchange / onviewchange / onafteredit 이벤트가 발생된다.
    //4. The onchange / onviewchange / onafteredit event is generated when the input data is initialized.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. '경기도1' 을 선택한다. 
    //5. Select 'Gyeonggi-do 1'.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_itemTable_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 5. 동일하게 onchange / onviewchange / onafteredit 이벤트가 발생된다.
    //5. The same onchange / onviewchange / onafteredit event is raised.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 6. 이번에는 '서울' 을 입력한다.
    //6. Enter 'Seoul' this time.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2').focus()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_input').value = '서울'");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_input').value = ''");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_button').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2').focus()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 6. 동일하게 onchange / onviewchange / onafteredit 이벤트가 발생된다. (그전에는 onviewchange 이벤트만 발생되었음.)
    //6. The same onchange / onviewchange / onafteredit event is raised. (Previously only the onviewchange event was fired.)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
